# Load and parse JSON files to extract potential topics/themes/prompts
def extract_json_snippets(file_path):
    with open(file_path, 'r', encoding='utf-8') as f:
        try:
            data = json.load(f)
            if isinstance(data, dict):
                text = json.dumps(data, indent=2)
            elif isinstance(data, list):
                text = "\n".join(json.dumps(d, indent=2) for d in data)
            else:
                text = str(data)
            return text[:2000]  # return preview to keep things manageable for now
        except Exception as e:
            return f"Error parsing {file_path.name}: {e}"

# Load and parse Markdown files to extract topics and structured prompts
def extract_md_snippets(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()
            return content[:2000]
    except Exception as e:
        return f"Error parsing {file_path.name}: {e}"

